import React, { useState } from 'react';
import ChatContainer from '../components/Chat/ChatContainer';

const Home = () => {
  const [chatSubmitted, setChatSubmitted] = useState(false);
  const [currentPrompt, setCurrentPrompt] = useState('');

  return (
    <div className="flex-1 flex items-center justify-center p-8">
      <div className="w-full max-w-4xl">
        {/* Feature Announcement */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center px-4 py-2 bg-white/10 backdrop-blur-md border border-white/20 rounded-full text-white/90 text-sm mb-6">
            <span>Introducing Lovable for Models</span>
            <svg className="w-4 h-4 ml-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </div>

          {/* Main Title */}
          <h1 className="text-6xl md:text-7xl font-bold text-white mb-4">
            Build something{' '}
            <span className="inline-flex items-center">
              <div className="heart-icon mr-2"></div>
              <span className="gradient-text">Lovable</span>
            </span>
          </h1>

          {/* Subtitle */}
          <p className="text-xl text-white/80 mb-12 max-w-2xl mx-auto">
            Create AI object detection models by chatting with AI. Describe what you want to detect, and we'll build it for you.
          </p>
        </div>

        {/* Chat Container */}
        <ChatContainer 
          chatSubmitted={chatSubmitted}
          setChatSubmitted={setChatSubmitted}
          currentPrompt={currentPrompt}
          setCurrentPrompt={setCurrentPrompt}
        />
      </div>
    </div>
  );
};

export default Home;
